import { createLocalAccountIssuer } from "@better-auth/core/db";
import { createEmailVerificationToken } from "better-auth/api";
import { and, eq, inArray, isNull, lt, or, sql } from "drizzle-orm";
import { Elysia, t } from "elysia";

import { createDb } from "../db";
import { user } from "../db/auth-schema";
import {
  bootstrapState,
  humanPrincipals,
  invitations,
  principals,
  rateLimitBuckets,
  systemRoleGrants,
  systemRoles,
} from "../db/domain-schema";
import {
  type AuthEnvironment,
  type AuthInstance,
  deliverEmail,
  isLocalEnvironment,
  readDevelopmentEmailSink,
} from "./auth";

type BootstrapStatus = "uninitialized" | "reserved" | "user-created" | "completed";

type BootstrapState = {
  status: BootstrapStatus;
  reservation_id: string | null;
  email: string | null;
  user_id: string | null;
  principal_id: string | null;
  reserved_at: number | null;
};

type InvitationStatus = "pending" | "claimed" | "completed" | "revoked" | "expired";

type Invitation = {
  id: string;
  token_hash: string;
  email: string;
  name: string | null;
  status: InvitationStatus;
  expires_at: number;
  invited_by_principal_id: string;
  claimed_user_id: string | null;
  claimed_principal_id: string | null;
  system_role_keys: string;
  claimed_at: number | null;
};

type ManagedUser = {
  id: string;
  email: string;
  name: string;
  emailVerified: boolean;
  createdAt: Date;
  updatedAt: Date;
  image?: string | null;
};

type Actor = {
  principalId: string;
  userId: string;
  roleKeys: Set<string>;
};

type BootstrapTokenBody = {
  bootstrapToken?: string;
  token?: string;
};

type BootstrapCompleteBody = BootstrapTokenBody & {
  reservationId?: string;
  email: string;
  name: string;
  password: string;
};

type InvitationCreateBody = {
  email: string;
  name?: string;
  expiresIn?: number;
  expiresInSeconds?: number;
  systemRoleKeys?: string[];
};

type InvitationAcceptBody = {
  email?: string;
  name?: string;
  password: string;
};

const emailSchema = t.String({ format: "email", maxLength: 320, minLength: 3 });
const tokenSchema = t.String({ maxLength: 1024, minLength: 1 });
const idSchema = t.String({ maxLength: 256, minLength: 1 });
const bootstrapTokenBodySchema = t.Object({
  bootstrapToken: t.Optional(tokenSchema),
  token: t.Optional(tokenSchema),
});
const bootstrapCompleteBodySchema = t.Object({
  bootstrapToken: t.Optional(tokenSchema),
  email: emailSchema,
  name: t.String({ maxLength: 160, minLength: 1 }),
  password: t.String({ maxLength: 256, minLength: 8 }),
  reservationId: t.Optional(idSchema),
  token: t.Optional(tokenSchema),
});
const invitationCreateBodySchema = t.Object({
  email: emailSchema,
  expiresIn: t.Optional(t.Integer({ maximum: 60 * 60 * 24 * 30, minimum: 1 })),
  expiresInSeconds: t.Optional(t.Integer({ maximum: 60 * 60 * 24 * 30, minimum: 1 })),
  name: t.Optional(t.String({ maxLength: 160, minLength: 1 })),
  systemRoleKeys: t.Optional(t.Array(t.String({ maxLength: 64, minLength: 1 }), { maxItems: 3 })),
});
const invitationAcceptBodySchema = t.Object({
  email: t.Optional(emailSchema),
  name: t.Optional(t.String({ maxLength: 160, minLength: 1 })),
  password: t.String({ maxLength: 256, minLength: 8 }),
});
const tokenParamsSchema = t.Object({ token: tokenSchema });
const userParamsSchema = t.Object({ id: idSchema });

class M1Error extends Error {
  readonly status: 400 | 401 | 403 | 404 | 409 | 429 | 500;

  constructor(readonly statusCode: 400 | 401 | 403 | 404 | 409 | 429 | 500) {
    super("The request could not be completed.");
    this.name = "M1Error";
    this.status = statusCode;
  }
}

export function normalizeEmail(email: string) {
  return email.normalize("NFKC").trim().toLowerCase();
}

function normalizeName(name: string | undefined, fallback: string) {
  const value = name?.normalize("NFKC").trim() || fallback;
  if (!value) throw new M1Error(400);
  return value;
}

function toBase64Url(bytes: Uint8Array) {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/, "");
}

async function sha256Bytes(value: string) {
  return new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value)));
}

export async function sha256Base64Url(value: string) {
  return toBase64Url(await sha256Bytes(value));
}

function constantTimeEqual(left: Uint8Array, right: Uint8Array) {
  const length = Math.max(left.length, right.length);
  let difference = left.length ^ right.length;

  for (let index = 0; index < length; index += 1) {
    difference |= (left[index] ?? 0) ^ (right[index] ?? 0);
  }

  return difference === 0;
}

async function validateBootstrapToken(environment: AuthEnvironment, suppliedToken: string) {
  const configuredToken = environment.BOOTSTRAP_TOKEN;
  const expectedToken = isStrongBootstrapToken(configuredToken)
    ? configuredToken
    : "bootstrap-token-not-configured";
  const [suppliedHash, expectedHash] = await Promise.all([
    sha256Bytes(suppliedToken),
    sha256Bytes(expectedToken),
  ]);

  return isStrongBootstrapToken(configuredToken) && constantTimeEqual(suppliedHash, expectedHash);
}

function isStrongBootstrapToken(token: string | undefined): token is string {
  return Boolean(token && token.length >= 32 && new Set(token).size >= 12);
}

function randomToken() {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  return toBase64Url(bytes);
}

function principalIdForUser(userId: string) {
  return `human_${userId}`;
}

function requestAddress(request: Request) {
  const cloudflareAddress = request.headers.get("cf-connecting-ip")?.trim();
  if (cloudflareAddress) return cloudflareAddress;

  const forwarded = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim();
  return request.url.startsWith("http://localhost") || request.url.startsWith("http://127.0.0.1")
    ? forwarded || "local"
    : "unknown";
}

async function consumeM1RateLimit(
  database: D1Database,
  key: string,
  max: number,
  windowSeconds: number,
) {
  const now = Date.now();
  const windowMilliseconds = windowSeconds * 1000;
  const bucket = await database
    .prepare(
      `INSERT INTO rate_limit_buckets
        (bucket_key, window_started_at, count, updated_at)
       VALUES (?, ?, 1, ?)
       ON CONFLICT(bucket_key) DO UPDATE SET
         count = CASE
           WHEN rate_limit_buckets.window_started_at + ? <= ? THEN 1
           ELSE rate_limit_buckets.count + 1
         END,
         window_started_at = CASE
           WHEN rate_limit_buckets.window_started_at + ? <= ? THEN ?
           ELSE rate_limit_buckets.window_started_at
         END,
         updated_at = ?
       RETURNING count, window_started_at`,
    )
    .bind(key, now, now, windowMilliseconds, now, windowMilliseconds, now, now, now)
    .first<{ count: number; window_started_at: number }>();

  if (!bucket) throw new M1Error(500);

  if (bucket.count === 1) {
    const db = createDb(database);
    await db
      .delete(rateLimitBuckets)
      .where(lt(rateLimitBuckets.updatedAt, now - 24 * 60 * 60 * 1000))
      .run();
  }

  return bucket.count <= max;
}

async function enforceRateLimit(
  environment: AuthEnvironment,
  request: Request,
  bucket: string,
  max: number,
  windowSeconds: number,
) {
  const allowed = await consumeM1RateLimit(
    environment.DB,
    `m1:${bucket}:${requestAddress(request)}`,
    max,
    windowSeconds,
  );
  if (!allowed) throw new M1Error(429);
}

function auditStatement(
  database: D1Database,
  id: string,
  eventType: string,
  actorPrincipalId: string | null,
  subjectPrincipalId: string | null,
  subjectUserId: string | null,
  metadata: Record<string, unknown>,
  createdAt: number,
) {
  return database
    .prepare(
      `INSERT OR IGNORE INTO audit_events
        (id, event_type, actor_principal_id, subject_principal_id, subject_user_id, metadata, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
    )
    .bind(
      id,
      eventType,
      actorPrincipalId,
      subjectPrincipalId,
      subjectUserId,
      JSON.stringify(metadata),
      createdAt,
    );
}

function outboxStatement(
  database: D1Database,
  id: string,
  eventType: string,
  aggregateType: string,
  aggregateId: string,
  payload: Record<string, unknown>,
  createdAt: number,
) {
  return database
    .prepare(
      `INSERT OR IGNORE INTO outbox_events
        (id, dedupe_key, event_type, aggregate_type, aggregate_id, payload,
         status, attempts, available_at, created_at)
       VALUES (?, ?, ?, ?, ?, ?, 'pending', 0, ?, ?)`,
    )
    .bind(
      id,
      id,
      eventType,
      aggregateType,
      aggregateId,
      JSON.stringify(payload),
      createdAt,
      createdAt,
    );
}

function auditStatementWhen(
  database: D1Database,
  id: string,
  eventType: string,
  actorPrincipalId: string | null,
  subjectPrincipalId: string | null,
  subjectUserId: string | null,
  metadata: Record<string, unknown>,
  createdAt: number,
  condition: string,
  conditionValues: readonly unknown[],
) {
  return database
    .prepare(
      `INSERT OR IGNORE INTO audit_events
        (id, event_type, actor_principal_id, subject_principal_id, subject_user_id, metadata, created_at)
       SELECT ?, ?, ?, ?, ?, ?, ?
        WHERE EXISTS (${condition})`,
    )
    .bind(
      id,
      eventType,
      actorPrincipalId,
      subjectPrincipalId,
      subjectUserId,
      JSON.stringify(metadata),
      createdAt,
      ...conditionValues,
    );
}

function outboxStatementWhen(
  database: D1Database,
  id: string,
  eventType: string,
  aggregateType: string,
  aggregateId: string,
  payload: Record<string, unknown>,
  createdAt: number,
  condition: string,
  conditionValues: readonly unknown[],
) {
  return database
    .prepare(
      `INSERT OR IGNORE INTO outbox_events
        (id, dedupe_key, event_type, aggregate_type, aggregate_id, payload,
         status, attempts, available_at, created_at)
       SELECT ?, ?, ?, ?, ?, ?, 'pending', 0, ?, ?
        WHERE EXISTS (${condition})`,
    )
    .bind(
      id,
      id,
      eventType,
      aggregateType,
      aggregateId,
      JSON.stringify(payload),
      createdAt,
      createdAt,
      ...conditionValues,
    );
}

async function getBootstrapState(database: D1Database) {
  const row = await createDb(database)
    .select()
    .from(bootstrapState)
    .where(eq(bootstrapState.id, 1))
    .get();

  if (!row) throw new M1Error(500);
  return {
    status: row.status,
    reservation_id: row.reservationId,
    email: row.email,
    user_id: row.userId,
    principal_id: row.principalId,
    reserved_at: row.reservedAt,
  } satisfies BootstrapState;
}

function tokenFromBody(body: BootstrapTokenBody) {
  const token = body.bootstrapToken ?? body.token;
  if (!token) throw new M1Error(403);
  return token;
}

async function requireBootstrapToken(environment: AuthEnvironment, body: BootstrapTokenBody) {
  const token = tokenFromBody(body);
  if (!(await validateBootstrapToken(environment, token))) throw new M1Error(403);
  return token;
}

async function getActor(auth: AuthInstance, environment: AuthEnvironment, request: Request) {
  const session = await auth.api.getSession({
    headers: request.headers,
    query: { disableCookieCache: true, disableRefresh: true },
  });
  if (!session?.user || !session.user.emailVerified) throw new M1Error(401);

  const db = createDb(environment.DB);
  const principal = await db
    .select({ principalId: principals.id, userId: humanPrincipals.userId })
    .from(humanPrincipals)
    .innerJoin(principals, eq(principals.id, humanPrincipals.principalId))
    .where(
      and(
        eq(humanPrincipals.userId, session.user.id),
        eq(humanPrincipals.status, "active"),
        eq(humanPrincipals.disabled, false),
        eq(principals.type, "human"),
        eq(principals.status, "active"),
      ),
    )
    .get();
  if (!principal || principal.userId !== session.user.id) throw new M1Error(401);

  const roleRows = await db
    .select({ key: systemRoles.key })
    .from(systemRoleGrants)
    .innerJoin(systemRoles, eq(systemRoles.id, systemRoleGrants.roleId))
    .where(
      and(
        eq(systemRoleGrants.principalId, principal.principalId),
        isNull(systemRoleGrants.revokedAt),
      ),
    )
    .all();

  return {
    principalId: principal.principalId,
    roleKeys: new Set(roleRows.map((row) => row.key)),
    userId: session.user.id,
  } satisfies Actor;
}

async function requireRole(
  auth: AuthInstance,
  environment: AuthEnvironment,
  request: Request,
  roles: readonly string[],
) {
  const actor = await getActor(auth, environment, request);
  if (!roles.some((role) => actor.roleKeys.has(role))) throw new M1Error(403);
  return actor;
}

async function ensureControlledUser(
  auth: AuthInstance,
  email: string,
  name: string,
  password: string,
  existingUserId?: string | null,
  allowExistingCredential = false,
  existingSince?: number | null,
): Promise<ManagedUser> {
  const context = await auth.$context;
  let user = existingUserId ? await context.internalAdapter.findUserById(existingUserId) : null;

  if (!user) {
    const existing = await context.internalAdapter.findUserByEmail(email, {
      includeAccounts: true,
    });
    user = existing?.user ?? null;
    if (
      user &&
      !allowExistingCredential &&
      existing?.accounts.some((account) => account.providerId === "credential")
    ) {
      const createdAt = new Date(user.createdAt).getTime();
      if (!existingSince || createdAt < existingSince) throw new M1Error(409);
    }
  }
  if (user && normalizeEmail(user.email) !== email) throw new M1Error(409);

  if (!user) {
    const passwordHash = await context.password.hash(password);
    try {
      user = await context.internalAdapter.createUser(
        { email, emailVerified: false, name },
        { method: "email-password" },
      );
    } catch {
      user =
        (await context.internalAdapter.findUserByEmail(email, { includeAccounts: true }))?.user ??
        null;
      if (!user) throw new M1Error(500);
    }

    try {
      await context.internalAdapter.linkAccount({
        accountId: user.id,
        issuer: createLocalAccountIssuer("credential"),
        password: passwordHash,
        providerId: "credential",
        userId: user.id,
      });
    } catch {
      if (!(await context.internalAdapter.findCredentialAccount(user.id))) throw new M1Error(500);
    }
  } else {
    const credential = await context.internalAdapter.findCredentialAccount(user.id);
    if (!credential) {
      const passwordHash = await context.password.hash(password);
      try {
        await context.internalAdapter.linkAccount({
          accountId: user.id,
          issuer: createLocalAccountIssuer("credential"),
          password: passwordHash,
          providerId: "credential",
          userId: user.id,
        });
      } catch {
        if (!(await context.internalAdapter.findCredentialAccount(user.id))) throw new M1Error(500);
      }
    } else if (allowExistingCredential) {
      await context.internalAdapter.updatePassword(user.id, password);
    }
  }

  return user as ManagedUser;
}

async function sendVerificationEmail(auth: AuthInstance, user: ManagedUser) {
  if (user.emailVerified) return;
  const context = await auth.$context;
  const send = context.options.emailVerification?.sendVerificationEmail;
  if (!send) return;

  const token = await createEmailVerificationToken(context.secret, user.email);
  const callbackURL = encodeURIComponent("/sign-in");
  const url = `${context.baseURL}/verify-email?token=${token}&callbackURL=${callbackURL}`;
  await send({ user, token, url });
}

async function sendInvitationEmail(
  environment: AuthEnvironment,
  invitation: { email: string; token: string; expiresAt: number; name: string | null },
) {
  const url = `${environment.BETTER_AUTH_URL}/invite/${encodeURIComponent(invitation.token)}`;
  await deliverEmail(environment, {
    email: invitation.email,
    kind: "invitation",
    token: invitation.token,
    url,
  });
}

async function readHumanMapping(database: D1Database, userId: string) {
  const row = await createDb(database)
    .select({
      id: principals.id,
      type: principals.type,
      principalStatus: principals.status,
      userId: humanPrincipals.userId,
      humanStatus: humanPrincipals.status,
      disabled: humanPrincipals.disabled,
    })
    .from(humanPrincipals)
    .innerJoin(principals, eq(principals.id, humanPrincipals.principalId))
    .where(eq(humanPrincipals.userId, userId))
    .get();

  return row
    ? {
        id: row.id,
        type: row.type,
        principal_status: row.principalStatus,
        user_id: row.userId,
        human_status: row.humanStatus,
        disabled: row.disabled ? 1 : 0,
      }
    : undefined;
}

async function ensureHumanPrincipal(database: D1Database, userId: string, now: number) {
  const principalId = principalIdForUser(userId);
  const existingMapping = await readHumanMapping(database, userId);
  if (existingMapping && existingMapping.id !== principalId) throw new M1Error(409);
  if (
    existingMapping &&
    (existingMapping.type !== "human" ||
      existingMapping.principal_status !== "active" ||
      existingMapping.human_status !== "active" ||
      existingMapping.disabled !== 0)
  ) {
    throw new M1Error(409);
  }

  const existingPrincipal = await createDb(database)
    .select({ id: principals.id, type: principals.type, status: principals.status })
    .from(principals)
    .where(eq(principals.id, principalId))
    .get();
  if (
    existingPrincipal &&
    (existingPrincipal.type !== "human" || existingPrincipal.status !== "active")
  ) {
    throw new M1Error(409);
  }

  const db = createDb(database);
  await db.batch([
    db
      .insert(principals)
      .values({
        id: principalId,
        type: "human",
        status: "active",
        disabledAt: null,
        createdAt: now,
        updatedAt: now,
      })
      .onConflictDoUpdate({ target: principals.id, set: { updatedAt: now } }),
    db
      .insert(humanPrincipals)
      .values({
        principalId,
        userId,
        status: "active",
        disabled: false,
        disabledAt: null,
        createdAt: now,
        updatedAt: now,
      })
      .onConflictDoUpdate({
        target: humanPrincipals.principalId,
        set: { userId, updatedAt: now },
      }),
  ]);

  const mapping = await readHumanMapping(database, userId);
  if (
    !mapping ||
    mapping.id !== principalId ||
    mapping.principal_status !== "active" ||
    mapping.human_status !== "active" ||
    mapping.disabled !== 0
  ) {
    throw new M1Error(500);
  }

  return principalId;
}

function roleKeysFromStorage(value: string) {
  let parsed: unknown;
  try {
    parsed = JSON.parse(value);
  } catch {
    throw new M1Error(500);
  }
  if (!Array.isArray(parsed) || !parsed.every((key) => typeof key === "string")) {
    throw new M1Error(500);
  }
  return [...new Set(parsed)];
}

async function validateRoleKeys(database: D1Database, requested: readonly string[]) {
  const unique = [...new Set(requested)];
  if (unique.length > 3) throw new M1Error(400);
  if (unique.length === 0) return unique;

  const roles = await createDb(database)
    .select({ key: systemRoles.key })
    .from(systemRoles)
    .where(inArray(systemRoles.key, unique))
    .all();
  if (roles.length !== unique.length) throw new M1Error(400);

  return unique;
}

function grantBootstrapRoleStatement(
  database: D1Database,
  reservationId: string,
  userId: string,
  principalId: string,
  now: number,
) {
  return database
    .prepare(
      `INSERT INTO system_role_grants
        (id, principal_id, role_id, granted_by_principal_id, created_at)
       SELECT ?, ?, id, NULL, ?
         FROM system_roles
        WHERE key = 'root'
          AND EXISTS (
            SELECT 1
              FROM bootstrap_state
             WHERE id = 1
               AND status = 'completed'
               AND reservation_id = ?
               AND user_id = ?
          )
       ON CONFLICT(principal_id, role_id) DO UPDATE SET revoked_at = NULL`,
    )
    .bind(`system-role:${principalId}:root`, principalId, now, reservationId, userId);
}

function grantInvitationRoleStatement(
  database: D1Database,
  invitationId: string,
  userId: string,
  principalId: string,
  roleKey: string,
  grantedByPrincipalId: string | null,
  now: number,
) {
  return database
    .prepare(
      `INSERT INTO system_role_grants
        (id, principal_id, role_id, granted_by_principal_id, created_at)
       SELECT ?, ?, id, ?, ?
         FROM system_roles
        WHERE key = ?
          AND EXISTS (
            SELECT 1
              FROM invitations
             WHERE id = ?
               AND status = 'completed'
               AND claimed_user_id = ?
          )
       ON CONFLICT(principal_id, role_id) DO UPDATE SET revoked_at = NULL`,
    )
    .bind(
      `system-role:${principalId}:${roleKey}`,
      principalId,
      grantedByPrincipalId,
      now,
      roleKey,
      invitationId,
      userId,
    );
}

async function completeBootstrapDomain(
  database: D1Database,
  state: BootstrapState,
  user: ManagedUser,
  principalId: string,
  now: number,
) {
  const existingRoot = await createDb(database)
    .select({ principalId: systemRoleGrants.principalId })
    .from(systemRoleGrants)
    .innerJoin(systemRoles, eq(systemRoles.id, systemRoleGrants.roleId))
    .innerJoin(principals, eq(principals.id, systemRoleGrants.principalId))
    .innerJoin(humanPrincipals, eq(humanPrincipals.principalId, principals.id))
    .where(
      and(
        eq(systemRoles.key, "root"),
        isNull(systemRoleGrants.revokedAt),
        eq(principals.type, "human"),
        eq(principals.status, "active"),
        eq(humanPrincipals.status, "active"),
        eq(humanPrincipals.disabled, false),
      ),
    )
    .get();
  if (existingRoot && existingRoot.principalId !== principalId) throw new M1Error(409);

  const email = state.email ?? normalizeEmail(user.email);
  const eventId = `bootstrap:completed:${state.reservation_id ?? principalId}`;
  const results = await database.batch([
    database
      .prepare(
        `UPDATE bootstrap_state
            SET status = 'completed', principal_id = ?, completed_at = ?, updated_at = ?
          WHERE id = 1
            AND status IN ('reserved', 'user-created')
            AND reservation_id = ?
            AND email = ?
            AND user_id = ?
          RETURNING id`,
      )
      .bind(principalId, now, now, state.reservation_id, email, user.id),
    grantBootstrapRoleStatement(database, state.reservation_id ?? "", user.id, principalId, now),
    auditStatementWhen(
      database,
      eventId,
      "bootstrap.completed",
      null,
      principalId,
      user.id,
      { email },
      now,
      "SELECT 1 FROM bootstrap_state WHERE id = 1 AND status = 'completed' AND reservation_id = ? AND user_id = ?",
      [state.reservation_id, user.id],
    ),
    outboxStatementWhen(
      database,
      `bootstrap:completed:outbox:${state.reservation_id ?? principalId}`,
      "bootstrap.completed",
      "bootstrap",
      "1",
      { principalId, userId: user.id },
      now,
      "SELECT 1 FROM bootstrap_state WHERE id = 1 AND status = 'completed' AND reservation_id = ? AND user_id = ?",
      [state.reservation_id, user.id],
    ),
  ]);
  if (!results[0]?.results.length) throw new M1Error(409);
}

async function reserveBootstrap(
  environment: AuthEnvironment,
  body: BootstrapTokenBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "bootstrap-reserve", 50, 60);
  await requireBootstrapToken(environment, body);
  const state = await getBootstrapState(environment.DB);
  if (state.status === "completed") throw new M1Error(404);
  if (state.status !== "uninitialized") {
    if (!state.reservation_id) throw new M1Error(500);
    return { reservationId: state.reservation_id, status: state.status };
  }

  const reservationId = crypto.randomUUID();
  const now = Date.now();
  const results = await environment.DB.batch([
    environment.DB.prepare(
      `UPDATE bootstrap_state
              SET status = 'reserved', reservation_id = ?, reserved_at = ?, updated_at = ?
            WHERE id = 1 AND status = 'uninitialized'
            RETURNING reservation_id, status`,
    ).bind(reservationId, now, now),
    auditStatementWhen(
      environment.DB,
      `bootstrap:reserved:${reservationId}`,
      "bootstrap.reserved",
      null,
      null,
      null,
      {},
      now,
      "SELECT 1 FROM bootstrap_state WHERE id = 1 AND status = 'reserved' AND reservation_id = ? AND reserved_at = ?",
      [reservationId, now],
    ),
    outboxStatementWhen(
      environment.DB,
      `bootstrap:reserved:outbox:${reservationId}`,
      "bootstrap.reserved",
      "bootstrap",
      "1",
      { reservationId },
      now,
      "SELECT 1 FROM bootstrap_state WHERE id = 1 AND status = 'reserved' AND reservation_id = ? AND reserved_at = ?",
      [reservationId, now],
    ),
  ]);
  const reserved = results[0]?.results[0] as
    | { reservation_id: string; status: BootstrapStatus }
    | undefined;

  if (!reserved) {
    const racedState = await getBootstrapState(environment.DB);
    if (racedState.status === "completed" || !racedState.reservation_id) throw new M1Error(409);
    return { reservationId: racedState.reservation_id, status: racedState.status };
  }

  return { reservationId, status: reserved.status };
}

async function completeBootstrap(
  environment: AuthEnvironment,
  auth: AuthInstance,
  body: BootstrapCompleteBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "bootstrap-complete", 50, 60);
  await requireBootstrapToken(environment, body);
  const state = await getBootstrapState(environment.DB);
  if (state.status === "completed") {
    if (state.email && normalizeEmail(body.email) !== state.email) throw new M1Error(409);
    return { status: state.status, userId: state.user_id };
  }
  if (state.status === "uninitialized" || !state.reservation_id) throw new M1Error(409);
  if (body.reservationId && body.reservationId !== state.reservation_id) throw new M1Error(409);

  const email = normalizeEmail(body.email);
  if (state.email && state.email !== email) throw new M1Error(409);

  const context = await auth.$context;
  if (
    body.password.length < context.password.config.minPasswordLength ||
    body.password.length > context.password.config.maxPasswordLength
  ) {
    throw new M1Error(400);
  }

  if (!state.email) {
    const claimedEmail = await environment.DB.prepare(
      `UPDATE bootstrap_state
            SET email = ?, updated_at = ?
          WHERE id = 1
            AND status = 'reserved'
            AND reservation_id = ?
            AND (email IS NULL OR email = ?)
          RETURNING email`,
    )
      .bind(email, Date.now(), state.reservation_id, email)
      .first<{ email: string }>();
    if (!claimedEmail) {
      const racedState = await getBootstrapState(environment.DB);
      if (racedState.email !== email) throw new M1Error(409);
    }
  }

  const user = await ensureControlledUser(
    auth,
    email,
    normalizeName(body.name, email),
    body.password,
    state.user_id,
    false,
    state.reserved_at,
  );
  const marked = await environment.DB.prepare(
    `UPDATE bootstrap_state
          SET status = 'user-created', user_id = ?, user_created_at = COALESCE(user_created_at, ?), updated_at = ?
        WHERE id = 1
          AND status IN ('reserved', 'user-created')
          AND reservation_id = ?
          AND email = ?
          AND (user_id IS NULL OR user_id = ?)
        RETURNING user_id`,
  )
    .bind(user.id, Date.now(), Date.now(), state.reservation_id, email, user.id)
    .first<{ user_id: string }>();
  if (!marked) {
    const racedState = await getBootstrapState(environment.DB);
    if (racedState.user_id !== user.id) throw new M1Error(409);
  }

  const markedState = await getBootstrapState(environment.DB);
  await sendVerificationEmail(auth, user);
  const principalId = await ensureHumanPrincipal(environment.DB, user.id, Date.now());
  await completeBootstrapDomain(environment.DB, markedState, user, principalId, Date.now());

  return { principalId, status: "completed" as const, userId: user.id };
}

async function readInvitation(database: D1Database, tokenHash: string) {
  const row = await createDb(database)
    .select()
    .from(invitations)
    .where(eq(invitations.tokenHash, tokenHash))
    .get();

  return row
    ? {
        id: row.id,
        token_hash: row.tokenHash,
        email: row.email,
        name: row.name,
        status: row.status,
        expires_at: row.expiresAt,
        invited_by_principal_id: row.invitedByPrincipalId,
        claimed_user_id: row.claimedUserId,
        claimed_principal_id: row.claimedPrincipalId,
        system_role_keys: row.systemRoleKeys,
        claimed_at: row.claimedAt,
      }
    : undefined;
}

async function expireInvitation(
  environment: AuthEnvironment,
  invitation: Pick<Invitation, "id">,
  now: number,
) {
  const principalSubquery = `
    SELECT COALESCE(claimed_principal_id, 'human_' || claimed_user_id)
      FROM invitations
     WHERE id = ? AND status = 'expired' AND claimed_user_id IS NOT NULL`;
  await environment.DB.batch([
    environment.DB.prepare(
      `UPDATE invitations
          SET status = 'expired', updated_at = ?
        WHERE id = ?
          AND status IN ('pending', 'claimed')
          AND expires_at <= ?`,
    ).bind(now, invitation.id, now),
    environment.DB.prepare(
      `UPDATE human_principals
          SET status = 'disabled', disabled = 1, disabled_at = ?, updated_at = ?
        WHERE principal_id = (${principalSubquery})`,
    ).bind(now, now, invitation.id),
    environment.DB.prepare(
      `UPDATE principals
          SET status = 'disabled', disabled_at = ?, updated_at = ?
        WHERE id = (${principalSubquery}) AND status = 'active'`,
    ).bind(now, now, invitation.id),
    environment.DB.prepare(
      `DELETE FROM session
        WHERE user_id = (
          SELECT claimed_user_id
            FROM invitations
           WHERE id = ? AND status = 'expired' AND claimed_user_id IS NOT NULL
        )`,
    ).bind(invitation.id),
  ]);
}

async function createInvitation(
  environment: AuthEnvironment,
  actor: Actor,
  body: InvitationCreateBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "invitation-create", 30, 60);
  const email = normalizeEmail(body.email);
  const name = body.name ? normalizeName(body.name, email) : null;
  const requestedRoleKeys = await validateRoleKeys(environment.DB, body.systemRoleKeys ?? []);
  const existingMapping = await createDb(environment.DB)
    .select({ userId: humanPrincipals.userId })
    .from(humanPrincipals)
    .innerJoin(principals, eq(principals.id, humanPrincipals.principalId))
    .innerJoin(user, eq(user.id, humanPrincipals.userId))
    .where(
      and(
        eq(user.email, email),
        eq(principals.status, "active"),
        eq(humanPrincipals.status, "active"),
        eq(humanPrincipals.disabled, false),
      ),
    )
    .get();
  if (existingMapping) throw new M1Error(409);
  const existingInvitation = await createDb(environment.DB)
    .select({ id: invitations.id })
    .from(invitations)
    .where(and(eq(invitations.email, email), inArray(invitations.status, ["pending", "claimed"])))
    .get();
  if (existingInvitation) throw new M1Error(409);

  const token = randomToken();
  const tokenHash = await sha256Base64Url(token);
  const invitationId = crypto.randomUUID();
  const now = Date.now();
  const requestedLifetime = body.expiresInSeconds ?? body.expiresIn ?? 60 * 60 * 24 * 7;
  const expiresAt = now + requestedLifetime * 1000;

  try {
    await environment.DB.batch([
      environment.DB.prepare(
        `INSERT INTO invitations
            (id, token_hash, email, name, status, expires_at, invited_by_principal_id, system_role_keys, created_at, updated_at)
           VALUES (?, ?, ?, ?, 'pending', ?, ?, ?, ?, ?)`,
      ).bind(
        invitationId,
        tokenHash,
        email,
        name,
        expiresAt,
        actor.principalId,
        JSON.stringify(requestedRoleKeys),
        now,
        now,
      ),
      auditStatement(
        environment.DB,
        `invitation:created:${invitationId}`,
        "invitation.created",
        actor.principalId,
        null,
        null,
        { email, expiresAt },
        now,
      ),
      outboxStatement(
        environment.DB,
        `invitation:created:outbox:${invitationId}`,
        "invitation.created",
        "invitation",
        invitationId,
        { email, expiresAt },
        now,
      ),
    ]);
  } catch (error) {
    const conflictingInvitation = await createDb(environment.DB)
      .select({ id: invitations.id })
      .from(invitations)
      .where(and(eq(invitations.email, email), inArray(invitations.status, ["pending", "claimed"])))
      .get();
    if (conflictingInvitation) throw new M1Error(409);
    throw error;
  }

  try {
    await sendInvitationEmail(environment, { email, expiresAt, name, token });
  } catch (error) {
    await environment.DB.batch([
      environment.DB.prepare("DELETE FROM audit_events WHERE id = ?").bind(
        `invitation:created:${invitationId}`,
      ),
      environment.DB.prepare("DELETE FROM outbox_events WHERE dedupe_key = ?").bind(
        `invitation:created:outbox:${invitationId}`,
      ),
      environment.DB.prepare("DELETE FROM invitations WHERE id = ? AND status = 'pending'").bind(
        invitationId,
      ),
    ]);
    throw error;
  }
  return { email, expiresAt, id: invitationId, token };
}

async function getPublicInvitation(environment: AuthEnvironment, token: string, request: Request) {
  await enforceRateLimit(environment, request, "invitation-read", 60, 60);
  const invitation = await readInvitation(environment.DB, await sha256Base64Url(token));
  if (!invitation) throw new M1Error(404);
  const now = Date.now();
  if (
    (invitation.status === "pending" || invitation.status === "claimed") &&
    invitation.expires_at <= now
  ) {
    await expireInvitation(environment, invitation, now);
    throw new M1Error(404);
  }
  if (invitation.status === "expired") {
    await expireInvitation(environment, invitation, now);
    throw new M1Error(404);
  }
  if (invitation.status !== "pending" && invitation.status !== "claimed") throw new M1Error(404);
  return {
    email: invitation.email,
    expiresAt: invitation.expires_at,
    name: invitation.name,
    status: invitation.status,
  };
}

async function claimInvitationWithAuth(
  environment: AuthEnvironment,
  auth: AuthInstance,
  token: string,
  body: InvitationAcceptBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "invitation-accept", 30, 60);
  const invitation = await readInvitation(environment.DB, await sha256Base64Url(token));
  if (!invitation) throw new M1Error(404);
  const now = Date.now();
  const suppliedEmail = body.email ? normalizeEmail(body.email) : invitation.email;
  if (suppliedEmail !== invitation.email) throw new M1Error(400);
  const context = await auth.$context;
  if (
    body.password.length < context.password.config.minPasswordLength ||
    body.password.length > context.password.config.maxPasswordLength
  ) {
    throw new M1Error(400);
  }

  let current = invitation;
  if (current.status === "pending") {
    if (current.expires_at <= now) {
      await expireInvitation(environment, current, now);
      throw new M1Error(404);
    }
    const claimed = await environment.DB.prepare(
      `UPDATE invitations
            SET status = 'claimed', claimed_at = ?, updated_at = ?
          WHERE id = ? AND status = 'pending' AND expires_at > ?
        RETURNING id, token_hash, email, name, status, expires_at,
                  invited_by_principal_id, claimed_user_id, claimed_principal_id,
                  system_role_keys, claimed_at`,
    )
      .bind(now, now, current.id, now)
      .first<Invitation>();
    current = claimed ?? (await readInvitation(environment.DB, current.token_hash)) ?? current;
  }
  if (current.status === "pending" || current.status === "revoked") {
    throw new M1Error(409);
  }
  if (current.status === "expired") {
    await expireInvitation(environment, current, now);
    throw new M1Error(409);
  }
  if (current.expires_at <= now) {
    await expireInvitation(environment, current, now);
    throw new M1Error(409);
  }
  if (current.status === "completed") throw new M1Error(409);

  const existingUser = await createDb(environment.DB)
    .select({ id: user.id })
    .from(user)
    .where(eq(user.email, current.email))
    .get();
  const existingMapping = existingUser
    ? await readHumanMapping(environment.DB, existingUser.id)
    : undefined;
  const hasActiveMapping =
    existingMapping?.principal_status === "active" &&
    existingMapping.human_status === "active" &&
    existingMapping.disabled === 0;
  const managedUser = await ensureControlledUser(
    auth,
    current.email,
    normalizeName(body.name, current.name ?? current.email),
    body.password,
    current.claimed_user_id,
    Boolean(current.claimed_user_id) || !hasActiveMapping,
    current.claimed_at,
  );
  const marked = await environment.DB.prepare(
    `UPDATE invitations
          SET claimed_user_id = ?, updated_at = ?
        WHERE id = ? AND status = 'claimed'
          AND (claimed_user_id IS NULL OR claimed_user_id = ?)
        RETURNING claimed_user_id`,
  )
    .bind(managedUser.id, Date.now(), current.id, managedUser.id)
    .first<{ claimed_user_id: string }>();
  if (!marked) {
    const racedInvitation = await readInvitation(environment.DB, current.token_hash);
    if (!racedInvitation || racedInvitation.claimed_user_id !== managedUser.id)
      throw new M1Error(409);
    current = racedInvitation;
  } else {
    current = (await readInvitation(environment.DB, current.token_hash)) ?? current;
  }
  if (current.status !== "claimed") throw new M1Error(409);

  const roleKeys = await validateRoleKeys(
    environment.DB,
    roleKeysFromStorage(current.system_role_keys),
  );
  await sendVerificationEmail(auth, managedUser);
  const principalId = await ensureHumanPrincipal(environment.DB, managedUser.id, Date.now());
  const eventId = `invitation:completed:${current.id}`;
  const completedAt = Date.now();
  const statements = [
    environment.DB.prepare(
      `UPDATE invitations
          SET status = 'completed', claimed_principal_id = ?, completed_at = ?, updated_at = ?
          WHERE id = ? AND status = 'claimed' AND claimed_user_id = ?
            AND expires_at > ?
        RETURNING id`,
    ).bind(principalId, completedAt, completedAt, current.id, managedUser.id, completedAt),
    ...roleKeys.map((roleKey) =>
      grantInvitationRoleStatement(
        environment.DB,
        current.id,
        managedUser.id,
        principalId,
        roleKey,
        current.invited_by_principal_id,
        completedAt,
      ),
    ),
    auditStatementWhen(
      environment.DB,
      eventId,
      "invitation.completed",
      current.invited_by_principal_id,
      principalId,
      managedUser.id,
      { email: current.email },
      completedAt,
      "SELECT 1 FROM invitations WHERE id = ? AND status = 'completed' AND claimed_user_id = ?",
      [current.id, managedUser.id],
    ),
    outboxStatementWhen(
      environment.DB,
      `invitation:completed:outbox:${current.id}`,
      "invitation.completed",
      "invitation",
      current.id,
      { principalId, userId: managedUser.id },
      completedAt,
      "SELECT 1 FROM invitations WHERE id = ? AND status = 'completed' AND claimed_user_id = ?",
      [current.id, managedUser.id],
    ),
  ];
  const results = await environment.DB.batch(statements);
  const completionResult = results[0];
  if (!completionResult?.results.length) {
    await expireInvitation(environment, current, completedAt);
    throw new M1Error(409);
  }
  return {
    email: managedUser.email,
    principalId,
    status: "accepted" as const,
    userId: managedUser.id,
  };
}

async function resolveInvitationForRevoke(database: D1Database, identifier: string) {
  const db = createDb(database);
  const byId = await db
    .select({ id: invitations.id, status: invitations.status })
    .from(invitations)
    .where(eq(invitations.id, identifier))
    .get();
  if (byId) return byId;
  const tokenHash = await sha256Base64Url(identifier);
  return db
    .select({ id: invitations.id, status: invitations.status })
    .from(invitations)
    .where(eq(invitations.tokenHash, tokenHash))
    .get();
}

async function revokeInvitation(
  environment: AuthEnvironment,
  actor: Actor,
  identifier: string,
  request: Request,
) {
  await enforceRateLimit(environment, request, "invitation-revoke", 30, 60);
  const invitation = await resolveInvitationForRevoke(environment.DB, identifier);
  if (!invitation) throw new M1Error(404);
  const now = Date.now();
  const results = await environment.DB.batch([
    environment.DB.prepare(
      `UPDATE invitations
            SET status = 'revoked', revoked_at = ?, updated_at = ?
           WHERE id = ? AND status = 'pending'
           RETURNING id`,
    ).bind(now, now, invitation.id),
    auditStatementWhen(
      environment.DB,
      `invitation:revoked:${invitation.id}`,
      "invitation.revoked",
      actor.principalId,
      null,
      null,
      { invitationId: invitation.id },
      now,
      "SELECT 1 FROM invitations WHERE id = ? AND status = 'revoked' AND revoked_at = ?",
      [invitation.id, now],
    ),
    outboxStatementWhen(
      environment.DB,
      `invitation:revoked:outbox:${invitation.id}`,
      "invitation.revoked",
      "invitation",
      invitation.id,
      {},
      now,
      "SELECT 1 FROM invitations WHERE id = ? AND status = 'revoked' AND revoked_at = ?",
      [invitation.id, now],
    ),
  ]);
  if (!results[0]?.results.length) {
    const current = await resolveInvitationForRevoke(environment.DB, identifier);
    if (current?.status !== "revoked") throw new M1Error(409);
  }
  return { id: invitation.id, status: "revoked" as const };
}

async function resolveHumanPrincipal(database: D1Database, identifier: string) {
  const db = createDb(database);
  const principal = await db
    .select({
      principalId: principals.id,
      principalStatus: principals.status,
      userId: humanPrincipals.userId,
      humanStatus: humanPrincipals.status,
      disabled: humanPrincipals.disabled,
    })
    .from(principals)
    .innerJoin(humanPrincipals, eq(humanPrincipals.principalId, principals.id))
    .where(or(eq(principals.id, identifier), eq(humanPrincipals.userId, identifier)))
    .get();
  if (!principal) return undefined;

  const rootGrant = await db
    .select({ id: systemRoleGrants.id })
    .from(systemRoleGrants)
    .innerJoin(systemRoles, eq(systemRoles.id, systemRoleGrants.roleId))
    .where(
      and(
        eq(systemRoleGrants.principalId, principal.principalId),
        isNull(systemRoleGrants.revokedAt),
        eq(systemRoles.key, "root"),
      ),
    )
    .get();

  return {
    principal_id: principal.principalId,
    principal_status: principal.principalStatus,
    user_id: principal.userId,
    human_status: principal.humanStatus,
    disabled: principal.disabled ? 1 : 0,
    is_root: rootGrant ? 1 : 0,
  };
}

async function activeRootCount(database: D1Database) {
  const row = await createDb(database)
    .select({ count: sql<number>`count(*)` })
    .from(principals)
    .innerJoin(humanPrincipals, eq(humanPrincipals.principalId, principals.id))
    .innerJoin(systemRoleGrants, eq(systemRoleGrants.principalId, principals.id))
    .innerJoin(systemRoles, eq(systemRoles.id, systemRoleGrants.roleId))
    .where(
      and(
        eq(principals.type, "human"),
        eq(principals.status, "active"),
        eq(humanPrincipals.status, "active"),
        eq(humanPrincipals.disabled, false),
        isNull(systemRoleGrants.revokedAt),
        eq(systemRoles.key, "root"),
      ),
    )
    .get();
  return row?.count ?? 0;
}

async function setUserDisabled(
  environment: AuthEnvironment,
  auth: AuthInstance,
  actor: Actor,
  identifier: string,
  disabled: boolean,
  request: Request,
) {
  await enforceRateLimit(environment, request, disabled ? "user-disable" : "user-enable", 60, 60);
  const target = await resolveHumanPrincipal(environment.DB, identifier);
  if (!target) throw new M1Error(404);
  if (
    target.principal_status === (disabled ? "disabled" : "active") &&
    target.human_status === (disabled ? "disabled" : "active")
  ) {
    if (disabled) {
      const context = await auth.$context;
      await context.internalAdapter.deleteUserSessions(target.user_id);
    }
    return {
      status: disabled ? ("disabled" as const) : ("active" as const),
      userId: target.user_id,
    };
  }
  if (disabled && target.is_root === 1 && (await activeRootCount(environment.DB)) <= 1) {
    throw new M1Error(409);
  }

  const now = Date.now();
  const nextStatus = disabled ? "disabled" : "active";
  const mutation = environment.DB.prepare(
    disabled
      ? `UPDATE principals
              SET status = 'disabled', disabled_at = ?, updated_at = ?
            WHERE id = ? AND type = 'human' AND status = 'active'
              AND (
                NOT EXISTS (
                  SELECT 1
                    FROM system_role_grants AS own_grant
                    JOIN system_roles AS own_role ON own_role.id = own_grant.role_id
                   WHERE own_grant.principal_id = principals.id
                     AND own_grant.revoked_at IS NULL
                     AND own_role.key = 'root'
                )
                OR (
                  SELECT COUNT(*)
                    FROM principals AS root_principal
                    JOIN human_principals AS root_human ON root_human.principal_id = root_principal.id
                    JOIN system_role_grants AS root_grant ON root_grant.principal_id = root_principal.id
                    JOIN system_roles AS root_role ON root_role.id = root_grant.role_id
                   WHERE root_principal.type = 'human'
                     AND root_principal.status = 'active'
                     AND root_human.status = 'active'
                     AND root_human.disabled = 0
                     AND root_grant.revoked_at IS NULL
                     AND root_role.key = 'root'
                ) > 1
              )
            RETURNING id`
      : `UPDATE principals
              SET status = 'active', disabled_at = NULL, updated_at = ?
             WHERE id = ? AND type = 'human' AND status = 'disabled'
             RETURNING id`,
  ).bind(...(disabled ? [now, now, target.principal_id] : [now, target.principal_id]));

  const results = await environment.DB.batch([
    mutation,
    environment.DB.prepare(
      `UPDATE human_principals
          SET status = ?, disabled = ?, disabled_at = ?, updated_at = ?
          WHERE principal_id = ?
            AND EXISTS (
              SELECT 1 FROM principals
               WHERE id = ? AND status = ? AND updated_at = ?
            )`,
    ).bind(
      nextStatus,
      disabled ? 1 : 0,
      disabled ? now : null,
      now,
      target.principal_id,
      target.principal_id,
      nextStatus,
      now,
    ),
    auditStatementWhen(
      environment.DB,
      `user:${disabled ? "disabled" : "enabled"}:${target.principal_id}:${now}`,
      `user.${disabled ? "disabled" : "enabled"}`,
      actor.principalId,
      target.principal_id,
      target.user_id,
      {},
      now,
      "SELECT 1 FROM principals WHERE id = ? AND status = ? AND updated_at = ?",
      [target.principal_id, nextStatus, now],
    ),
    outboxStatementWhen(
      environment.DB,
      `user:${disabled ? "disabled" : "enabled"}:outbox:${target.principal_id}:${now}`,
      `user.${disabled ? "disabled" : "enabled"}`,
      "principal",
      target.principal_id,
      { userId: target.user_id, status: nextStatus },
      now,
      "SELECT 1 FROM principals WHERE id = ? AND status = ? AND updated_at = ?",
      [target.principal_id, nextStatus, now],
    ),
  ]);

  if (!results[0]?.results.length) {
    const current = await resolveHumanPrincipal(environment.DB, identifier);
    if (current?.principal_status === nextStatus && current.human_status === nextStatus) {
      return {
        status: disabled ? ("disabled" as const) : ("active" as const),
        userId: current.user_id,
      };
    }
    throw new M1Error(409);
  }

  if (disabled) {
    const context = await auth.$context;
    await context.internalAdapter.deleteUserSessions(target.user_id);
  }

  return { status: disabled ? ("disabled" as const) : ("active" as const), userId: target.user_id };
}

