        "invitation.created",
        actor.principalId,
        null,
        null,
        { email, expiresAt },
        now,
      ),
      outboxStatement(
        environment.DB,
        `invitation:created:outbox:${invitationId}`,
        "invitation.created",
        "invitation",
        invitationId,
        { email, expiresAt },
        now,
      ),
    ]);
  } catch (error) {
    const conflictingInvitation = await createDb(environment.DB)
      .select({ id: invitations.id })
